    67|function hashCode(code: string): string {
    68|  const salt = randomBytes(16).toString('hex');
    69|  const digest = scryptSync(code, salt, 32).toString('hex');
    70|  return `${CODE_HASH_PREFIX}:${salt}:${digest}`;
    71|}
