    73|function matchesCode(code: string, storedHash: string): boolean {
    74|  const [algorithm, salt, digest] = storedHash.split(':');
    75|  if (algorithm !== CODE_HASH_PREFIX || !salt || !digest) return false;
    76|  const candidate = scryptSync(code, salt, 32);
    77|  const expected = Buffer.from(digest, 'hex');
    78|  return candidate.length === expected.length && timingSafeEqual(candidate, expected);
