   108|async function readStore<T>(file: string, fallback: T): Promise<T> {
   109|  if (isDurableStoreConfigured()) {
   110|    try {
   111|      return await readDurableJson<T>(file, fallback);
   112|    } catch {
   113|      return fallback;
   114|    }
   115|  }
   116|  if (!canUseFilesystemFallback()) return fallback;
   117|  try {
   118|    const raw = await readFile(file, 'utf8');
   119|    return JSON.parse(raw) as T;
   120|  } catch {
   121|    return fallback;
   122|  }
   123|}
   124|
   125|async function writeStore<T>(file: string, value: T): Promise<void> {
   126|  if (isDurableStoreConfigured()) {
   127|    await writeDurableJson(file, value);
   128|    return;
   129|  }
   130|  if (!canUseFilesystemFallback()) {
   131|    throw new Error('Secure verification storage is unavailable.');
   132|  }
   133|  await mkdir(path.dirname(file), { recursive: true });
   134|  await writeFile(file, JSON.stringify(value, null, 2), 'utf8');
