   145|async function fallbackStoreCode(input: StoreCodeInput, code: string, expiresAt: Date): Promise<void> {
   146|  const codes = await readStore<FallbackCodesStore>(CODES_FILE(), {});
   147|  const nowDate = new Date();
   148|  pruneExpiredCodes(codes, nowDate);
   149|  const key = codeKey(input.userId, input.type);
   150|  const existing = codes[key];
   151|  const now = nowDate.toISOString();
   152|  if (existing && !existing.verifiedAt && new Date(existing.expiresAt) >= nowDate) {
   153|    if (nowDate.getTime() - new Date(existing.lastSentAt).getTime() < RESEND_COOLDOWN_MS) {
   154|      throw new Error('Please wait before requesting another verification code.');
   155|    }
   156|    if (existing.resendCount >= MAX_RESENDS) {
   157|      throw new Error('Verification resend limit reached. Please wait for the current code to expire.');
   158|    }
   159|  }
   160|  codes[key] = {
   161|    userId: input.userId,
   162|    type: input.type,
   163|    codeHash: hashCode(code),
   164|    attempts: 0,
   165|    resendCount: existing && !existing.verifiedAt ? existing.resendCount + 1 : 0,
   166|    expiresAt: expiresAt.toISOString(),
   167|    verifiedAt: null,
