async function getAuthenticatedUserId(request: Request): Promise<string | null> {
  const authHeader = request.headers.get('Authorization') || '';
  const match = authHeader.match(/^Bearer\s+(.+)$/i);
  const token = match?.[1]?.trim();
  if (!token) return null;

  try {
    const { data, error } = await getMemberAuthClient().auth.getUser(token);
    return error || !data.user ? null : data.user.id;
  } catch {
    return null;
  }
}

function getMemberAuthClient(): ReturnType<typeof createMemberAuthClient> {
  return createMemberAuthClient();
}

function createMemberAuthClient() {
  const url = process.env.SUPABASE_URL || process.env.EXPO_PUBLIC_SUPABASE_URL || '';
  const key = process.env.SUPABASE_ANON_KEY || process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY || '';
  return createClient(url, key, { auth: { persistSession: false, autoRefreshToken: false } });
}

async function requireAuthenticatedMember(request: Request): Promise<string | null> {
  return getAuthenticatedUserId(request);
}

